let tokens;
try {
  tokens = JSON.parse((process.env.MOCK_SCANNER_JSON) ?? '[]');
} catch (e) {
  tokens = [];
}
if (!Array.isArray(tokens) || tokens.length === 0) {
  const now = Date.now();
  tokens = [
    {
      tokenAddress: 'DezXAZ8z7PnrnRJjz3wXBoRgixCa6xjnB7YaB1pPB263',
      symbol: 'BONK',
      marketCap: 50000,
      liquidity: 20000,
      price: 1,
      pairCreatedAt: now - 10 * 60 * 1000
    }
  ];
}
return tokens.map(t => ({ json: t }));

const inputItems = $input.all();
const seen = new Set();
const results = [];

for (const item of inputItems) {
  const data = item.json.body ?? item.json;
  const rows = Array.isArray(data) ? data : (data?.tokenAddress ? [data] : (Array.isArray(data.tokens) ? data.tokens : []));

  for (const token of rows) {
    if (String(token.chainId || '').toLowerCase() !== 'solana' || !token.tokenAddress) continue;
    if (seen.has(token.tokenAddress)) continue;
    seen.add(token.tokenAddress);
    results.push({ json: { tokenAddress: token.tokenAddress, source: 'dexscreener-token-boosts' } });
  }
}

return results.slice(0, 30);

const fs = require('fs');
const now = Date.now();
const maxAgeMs = 6 * 60 * 60 * 1000;
const cooldownMs = 12 * 60 * 60 * 1000;
const cooldownPath = '/tmp/memebot_token_cooldown.json';

let cooldown = {};
try {
  cooldown = JSON.parse(fs.readFileSync(cooldownPath, 'utf8'));
} catch (e) {
  cooldown = {};
}

const freshCooldown = {};
for (const [address, seenAt] of Object.entries(cooldown)) {
  if (now - Number(seenAt || 0) < cooldownMs) freshCooldown[address] = Number(seenAt);
}

const scored = $input.all()
  .map(item => item.json)
  .map(token => {
    const marketCap = Number(token.marketCap || 0);
    const liquidity = Number(token.liquidity || 0);
    const volume5m = Number(token.volume5m || 0);
    const volume1h = Number(token.volume1h || 0);
    const volume24h = Number(token.volume24h || 0);
    const buys5m = Number(token.buys5m || 0);
    const sells5m = Number(token.sells5m || 0);
    const buys1h = Number(token.buys1h || 0);
    const sells1h = Number(token.sells1h || 0);
    const price = Number(token.price || 0);
    const priceChange5m = Number(token.priceChange5m || 0);
    const priceChange1h = Number(token.priceChange1h || 0);
    const pairCreatedAt = Number(token.pairCreatedAt || 0);
    const ageMs = pairCreatedAt > 0 ? now - pairCreatedAt : Number.POSITIVE_INFINITY;
    const buySellRatio5m = buys5m / Math.max(sells5m, 1);
    const buySellRatio1h = buys1h / Math.max(sells1h, 1);
    const liqToCapRatio = liquidity / Math.max(marketCap, 1);
    const volLiqRatio = volume1h / Math.max(liquidity, 1);

    // ═══════════════════════════════════════════════
    // ENTRY FILTERS v6 — relaxed to match boosted-token reality
    // ═══════════════════════════════════════════════
    const capOk = marketCap >= 20000 && marketCap <= 500000;
    const liquidityOk = liquidity >= 5000 && liquidity <= 500000;
    const ageOk = ageMs >= (3 * 60 * 1000) && ageMs <= maxAgeMs;
    const volumeOk = volume1h >= liquidity * 0.05;
    const volume5mOk = volume5m >= 200;
    const flowOk = buys5m >= 2 && buySellRatio5m >= 1.0;
    const flow1hOk = buys1h >= 5 && buySellRatio1h >= 0.8;
    const momentumOk = priceChange5m >= -3;
    const momentum1hOk = priceChange1h > -10;
    const priceOk = price > 0;
    const cooldownOk = !freshCooldown[token.tokenAddress];
    const liqRatioOk = liqToCapRatio >= 0.04;
    // v6: relaxed overheating from 2.5x to 5x
    const notOverheated = volLiqRatio <= 5;
    // v6: relaxed pump ceiling from 20% to 50%
    const notChasingTop = priceChange1h <= 50;
    // v6: relaxed 5m pump from 8% to 20%
    const notFomo5m = priceChange5m <= 20;

    // ═══════════════════════════════════════════════
    // SCORING v4 — penalizes overheating, rewards very fresh tokens
    // ═══════════════════════════════════════════════
    const liquidityScore = Math.min(liquidity / 20000, 1.5);
    // Volume score: sweet spot 1-5x liquidity, penalize above
    const volRaw = volLiqRatio;
    const volumeScore = volRaw <= 5 ? Math.min(volRaw * 0.5, 2) : Math.max(2 - (volRaw - 5) * 0.3, 0);
    const flowScore = Math.min(buySellRatio5m * 0.6 + buySellRatio1h * 0.4, 2.5);
    const momentumScore = priceChange5m > 5 ? 1.5 : priceChange5m > 3 ? 1.2 : priceChange5m > 1 ? 0.8 : 0;
    // Sweet spot: 35k-80k (early movers only, v4)
    const capScore = marketCap >= 35000 && marketCap <= 80000 ? 1.5 : (marketCap <= 100000 ? 0.7 : 0.2);
    const liqRatioScore = liqToCapRatio >= 0.2 ? 1 : liqToCapRatio >= 0.12 ? 0.5 : 0;
    // bonus for fresh tokens (under 2h old) — catching momentum early
    const freshnessScore = ageMs <= (2 * 60 * 60 * 1000) ? 0.5 : 0;
    // v5: strong bonus for very fresh tokens (under 20 min old) — catch early curve
    const veryFreshScore = ageMs <= (20 * 60 * 1000) ? 2.0 : ageMs <= (60 * 60 * 1000) ? 0.8 : 0;
    const score = liquidityScore + volumeScore + flowScore + momentumScore + capScore + liqRatioScore + freshnessScore + veryFreshScore;

    return {
      token,
      score,
      passes: capOk && liquidityOk && ageOk && volumeOk && volume5mOk && flowOk && flow1hOk && momentumOk && momentum1hOk && priceOk && cooldownOk && liqRatioOk && notOverheated && notChasingTop && notFomo5m && Boolean(token.tokenAddress)
    };
  })
  .filter(row => row.passes)
  .sort((a, b) => b.score - a.score)
  .slice(0, 3);

try {
  fs.writeFileSync(cooldownPath, JSON.stringify(freshCooldown, null, 2));
} catch (e) {}

return scored.map(({ token, score }) => ({
  json: {
    tokenAddress: token.tokenAddress,
    symbol: token.symbol || 'UNKNOWN',
    marketCap: Number(token.marketCap),
    liquidity: Number(token.liquidity),
    volume5m: Number(token.volume5m || 0),
    volume1h: Number(token.volume1h || 0),
    volume24h: Number(token.volume24h || 0),
    buys5m: Number(token.buys5m || 0),
    sells5m: Number(token.sells5m || 0),
    buys1h: Number(token.buys1h || 0),
    sells1h: Number(token.sells1h || 0),
    priceChange5m: Number(token.priceChange5m || 0),
    priceChange1h: Number(token.priceChange1h || 0),
    price: Number(token.price),
    pairCreatedAt: Number(token.pairCreatedAt),
    candidateScore: Number(score.toFixed(4))
  }
}));

const root = $json.body ?? $json;
let pairs = [];
if (Array.isArray(root)) {
  pairs = root;
} else if (Array.isArray(root.pairs)) {
  pairs = root.pairs;
} else if (root.chainId) {
  pairs = [root];
}

const solanaPairs = pairs.filter(pair => String(pair.chainId || '').toLowerCase() === 'solana');
if (solanaPairs.length === 0) return [];

const pair = solanaPairs.sort((a, b) => Number(b.liquidity?.usd || 0) - Number(a.liquidity?.usd || 0))[0];
const txns = pair.txns || {};
const volume = pair.volume || {};
const priceChange = pair.priceChange || {};

return [{
  json: {
    tokenAddress: pair.baseToken?.address || $item(0).$node['Extract Tokens'].json.tokenAddress,
    symbol: pair.baseToken?.symbol || 'UNKNOWN',
    marketCap: Number(pair.marketCap || pair.fdv || 0),
    liquidity: Number(pair.liquidity?.usd || 0),
    price: Number(pair.priceUsd || 0),
    pairCreatedAt: Number(pair.pairCreatedAt || 0),
    pairAddress: pair.pairAddress || '',
    dexId: pair.dexId || '',
    volume5m: Number(volume.m5 || 0),
    volume1h: Number(volume.h1 || 0),
    volume6h: Number(volume.h6 || 0),
    volume24h: Number(volume.h24 || 0),
    buys5m: Number(txns.m5?.buys || 0),
    sells5m: Number(txns.m5?.sells || 0),
    buys1h: Number(txns.h1?.buys || 0),
    sells1h: Number(txns.h1?.sells || 0),
    priceChange5m: Number(priceChange.m5 || 0),
    priceChange1h: Number(priceChange.h1 || 0),
    priceChange6h: Number(priceChange.h6 || 0)
  }
}];
